foreach($additionalTranslations as $languageCode=>$entries)$translations[$languageCode]=array_merge($translations[$languageCode],$entries);

function t(string $key, array $replace=[]): string {
    global $translations,$lang;
    $value=$translations[$lang][$key] ?? $translations['sq'][$key] ?? $key;
    foreach($replace as $name=>$content) $value=str_replace('{'.$name.'}',(string)$content,$value);
    return $value;
}
function current_lang(): string { global $lang; return $lang; }
function language_url(string $language): string {
    $path=(string)parse_url($_SERVER['REQUEST_URI'] ?? '/index.php',PHP_URL_PATH);
    $query=[];parse_str((string)parse_url($_SERVER['REQUEST_URI'] ?? '',PHP_URL_QUERY),$query);
    unset($query['csrf']);$query['lang']=$language;
    return $path.'?'.http_build_query($query);
}
function product_copy(array $product,string $field): string {
    global $db;
    if(!in_array($field,['title','description'],true)) return '';
    $stmt=$db->prepare("SELECT $field FROM product_translations WHERE product_id=? AND lang=?");
    $stmt->execute([(int)$product['id'],current_lang()]);$value=$stmt->fetchColumn();
    return $value!==false?(string)$value:(string)$product[$field];
}
